use anyhow :: Context as _ ; use reqwest :: header :: HeaderMap ; use reqwest :: { Response , StatusCode , Url } ; # [doc = " Reads an HTTP error response body and formats a human-readable reason."] # [doc = ""] # [doc = " Returns the status code as a `u16` and a formatted string of the form"] # [doc = " `\"<status> Reason: <body>\"`, falling back to `\"<status> Reason: [Unknown]\"`"] # [doc = " when the body cannot be read or is empty."] pub async fn read_http_error_reason (response : Response) -> (u16 , String) { let status = response . status () ; let body = response . text () . await . ok () . filter (| b | ! b . is_empty ()) ; let reason = match body { Some (b) => format ! ("{status} Reason: {b}") , None => format ! ("{status} Reason: [Unknown]") , } ; (status . as_u16 () , reason) }